css:
.navbar-brand .app-logo {
    transition: transform 0.2s ease;
    cursor: pointer;
}

.navbar-brand .app-logo:hover {
    transform: scale(1.2);
}

.print-heading {
    text-align: right;
    text-transform: uppercase;
    font-weight: bold;
    padding-bottom: 5px;
    margin-bottom: 10px;
    border-bottom: 2px solid #ccc;
}

.print-format table.table-bordered {
    border-top: 2px solid #ddd;
}

.print-format th {
    background-color: #eee !important;
}

[document-status] {
    margin-bottom: 0 !important;
    margin-top: 0 !important;
}

.container.page-body {
    overflow-y: hidden;
}

.container {
    width: 98% !important;
}

.signature-box {
    height: 80px;
    text-align: center;
}


img.stamp {
    display: inline-block;
    width: 120px;
    margin-right: -15px;
}

img.signature_stamp {
    display: inline-block;
    width: 150px;
}

.page-break {
    padding: 10px 0 !important;
}

.custom-page {
    padding: 10px 0 !important;
}

h1 small,
h2 small,
h3 small,
h4 small,
h5 small,
h6 small,
.h1 small,
.h2 small,
.h3 small,
.h4 small,
.h5 small,
.h6 small,
h1 .small,
h2 .small,
h3 .small,
h4 .small,
h5 .small,
h6 .small,
.h1 .small,
.h2 .small,
.h3 .small,
.h4 .small,
.h5 .small,
.h6 .small {
    font-weight: normal;
    line-height: 1;
    color: inherit !important;
}

h6.uppercase,
.h6.uppercase {
    font-size: 12px;
    font-weight: 500;
}


.form-section .section-head .collapse-indicator {
    color: #aaa;
}

.octicon,
.mega-octicon {
    font: normal normal normal 18px/1 octicons;
}

.form-links .count {
    font-size: larger;
    font-weight: bold;
}

.letterhead-logo {
    display: inline-block;
    margin-right: 10px;
}

.letterhead-title {
    display: inline-block;
    vertical-align: middle;
    font-size: 25px;
    width: fit-content;
    white-space: nowrap;
}

.letterhead-address {
    text-align: center;
    font-size: 12px;
}


.company_trn {
    display: inline-block;
    /* padding: 100px; */
    /* text-align: start; */
    width: 50%;
    text-align: left;
    font-weight: bold;
}

.heading_right {
    display: inline-block;
    /* padding: 100px; */
    /* text-align: start; */
    width: 50%;
    text-align: right;
}

.data-field .print_label {
    padding-right: 5px !important;
}

.listview-main-section .page-form .octicon-search {
    display: none !important;
}

.listview-main-section .page-form {
    padding-left: 0px !important;
}

.tree-label,
.tree {
    font-size: large;
}

.control-label {
    font-weight: bold !important;
}

.link-btn {
    background: #fff;
}

.form-sidebar .sidebar-image-section .standard-image {
    font-size: 46px !important;
}

.sidebar-image-section {
    margin: 0 auto !important;
}

.custom-doc-title {
    font-size: larger;
    text-align: center;
}

.signature-hr {
    width: 60%;
    border: 0;
}

.print-format hr {
    margin: 5px;
}

.list-item__content--indicator {
    flex: 0;
}

.list-item .avatar {
    display: none;
}

.page-title {
    max-width: unset;
    padding: 0 2px;
}

.page-actions {
    padding: 0 2px;
}

.page-title .title-image:hover {
    opacity: 0.5;
}

.page-title .title-image {
    background-color: #eee !important;
    cursor: pointer;
    transition: all 0.6s;
    padding: 20px 0 !important;
}

.avatar-small {
    margin-right: 0px !important;
}

.standard-image {
    color: #111;
}




.editable-title .editable-indicator {
    display: inline-block;
}

span.editable-indicator {
    display: none;
}

.editable-indicator i {
    font-size: medium;
}

.editable-title .title-text {
    background-color: yellow;
    border-radius: 5px;
    padding: 5px;
    color: black;
}

.navbar-header .octicon {
    font-size: 22px;
}

.btn-sm,
.btn-group-sm>.btn {
    padding: 6px 12px;
}

.mrp_is_dirty {
    background-color: orange;
    border-color: orange;
}

.section-box {
    font-size: larger !important;
}

a.list-sidebar-link {
    padding: 15px;
    width: 100%;
}

a.list-sidebar-link.active,
a.list-sidebar-link:hover {
    background-color: #eee !important;
    border-radius: 0px !important;
    text-decoration: none !important;
}

.tags-placeholder {
    padding: 10px;
    background: #eee;
    font-size: 12px;
}

.navbar-fixed-top {
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}

.page-head {
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    margin-bottom: 10px;
}

.close-sidebar {
    position: fixed;
    top: 0;
    right: 0;
    opacity: 0.3;
    background: #000;
    z-index: 1041;
    height: 100%;
    width: 100%;
    transition: .2s ease !important;
    display: none;
}


@media (min-width: 992px) {
    .close-sidebar {
        display: none !important;
    }
}

.overlay-sidebar {
    transition: transform 0.2s ease !important;
}






.sub-heading {
    position: absolute !important;
    z-index: 0;
    top: 5px !important;
    width: 100% !important;
    text-align: center;
    right: 0 !important;
    margin: 0 !important;
}






.link-field.ui-front {
    width: 100%;
}

.table-multiselect.form-control input {
    width: 100%;
}


.sidebar-menu .list-link {
    /*margin:0 !important;*/
}

.layout-side-section .sidebar-menu {
    /*padding:0 !important;*/
}

.print-report-filters {
    margin-right: 5px;
}

.report-wrapper .dt-scrollable,
.datatable-wrapper .dt-scrollable {
    width: auto !important;
}


.search-dialog .modal-dialog {
    width: 85vw;
}

.form-inner-toolbar {
    padding: 0 !important;
}

.form-inner-toolbar .btn {
    margin: 1px !important;
    padding: 10px !important;
    border: 1px solid #ccc;
}

.navbar-form .awesomplete {
    width: 40vw;
}

.toggle-sidebar {
    display: none !important;
}

