    overflow-x: auto;
}

.form-grid .grid-body, .form-grid .grid-heading-row {
    width: 200%;
}

.form-grid .col-xs-3
{
    width:16.6%;
}

.form-grid .col-xs-2
{
    width:8.3%;
}

.form-grid .col-xs-1
{
    width:4.15%;
}

*/

.btn-open-row {
    opacity: 1;
}

.header-caption,
.footer-caption {
    font-size: 24px;
    font-weight: bold;
    color: red;

    position: absolute;
    top: 0;
    right: 0;
}

.header-caption-left {
    font-size: 24px;
    font-weight: bold;
    color: red;

    position: absolute;
    top: 0;
    left: 0;
}

.liked-by-popover .popover-content {
    overflow: auto !important;
}

.cursor-pointer {
    cursor: pointer;
}

.form-tabs-sticky-down {
    top: 0;
}



.input-with-feedback.form-control {
    font-weight: 800;
    border: 1px solid #ddd;
}

.input-with-feedback.form-control::placeholder {
    font-weight: 500;
}


.dropdown-menu {
    overflow-y: auto !important;
    max-height: 60vh !important;
}

.BetaPrintFormatBuilder {
    display: none;
}

@media (max-width: 991px) {
    #navbar-breadcrumbs li:first-child {
        display: none !important;
    }

    #navbar-breadcrumbs li:not(:first-child) {
        display: block !important;
    }
}

.page-head .page-head-content {
    height: auto !important;
    padding: 10px;
}

@media (max-width: 976px) {
    #page-Workspaces .custom-actions {
        display: none !important;
    }

    /* Hide everywhere EXCEPT list pages */
    .page-container:not([id^="page-List/"]) .custom-actions {
        display: none !important;
    }
}


.custom-actions {
    flex-wrap: wrap;
}

.print-format.landscape table {
    table-layout: fixed;
    overflow-wrap: break-word;
}

button.btn.btn-primary.btn-sm.primary-action.dirty {
    background: orange;
}

.search-bar {
    max-width: 100% !important;
}




.print-format-builder-sidebar {
    width: 200px !important;
    height: 200px !important;
    padding-bottom: 10px;
    padding-right:10px;
}

.navbar .navbar-brand {
    user-select: none;
}

.print-format {
    max-width: unset !important;
    max-height: unset !important;
}

.print-preview.landscape {
    max-width: 11.69in !important;
}

.page-break-message {
    display: none;
}
